(* [comment removed for export] *)
Definition Y1OPS (SEG q1 q2 q3 q4 : Z) : Prop :=
  0 <= q1 /\ q1 <= 2 * (q4 - 3 * SEG) /\ SEG <= q2 /\ q2 - SEG <= 2 * (q4 - 3 * SEG) /\
  2 * SEG <= q3 /\ q3 - 2 * SEG <= 2 * (q4 - 3 * SEG) /\ 3 * SEG <= q4.

